begin;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
-- All fixtures and queue rows below roll back. No provider requests are made.
do $$ declare actor uuid;oid uuid;iid uuid;sid uuid;sid2 uuid;ver integer;result jsonb;blocked boolean;tx jsonb;begin
 select id into actor from auth.users where raw_app_meta_data->>'store_role'='admin' limit 1;
 if actor is null then raise exception 'An existing store admin is required';end if;
 insert into public.orders(order_number,user_id,customer_name,customer_email,contact,items,estimated_total,currency,pricing_verified_at) values('TRK-1794840000000-OPS1',actor,'Rollback fixture','audit@example.test','audit','[{"name":"Test item","quantity":2,"unitPrice":50,"lineTotal":100,"shippingTotal":0}]',100,'GHS',now()) returning id into oid;
 select id into iid from private.order_items where order_id=oid;
 insert into public.payment_attempts(reference,order_id,amount,currency)values('TRK-ops-test-reference',oid,10000,'GHS');
 tx:=jsonb_build_object('reference','TRK-ops-test-reference','status','success','amount',10000,'currency','GHS','customer',jsonb_build_object('email','audit@example.test'),'metadata',jsonb_build_object('order_id',oid,'user_id',actor));
 blocked:=false;begin perform public.finalize_verified_payment(oid,'TRK-ops-test-reference',tx||'{"amount":1}');exception when raise_exception then blocked:=true;end;if not blocked then raise exception 'Wrong payment amount accepted';end if;
 perform public.finalize_verified_payment(oid,'TRK-ops-test-reference',tx);perform public.finalize_verified_payment(oid,'TRK-ops-test-reference',tx);
 if(select count(*) from private.order_jobs where order_id=oid and kind='receipt')<>1 or(select count(*) from private.order_audit where order_id=oid and action='payment_verified')<>1 then raise exception 'Payment was not idempotent';end if;
 sid:=(public.order_operations(actor,'create_shipment','{"label":"Rollback batch A"}')->>'id')::uuid;
 sid2:=(public.order_operations(actor,'create_shipment','{"label":"Rollback batch B"}')->>'id')::uuid;
 result:=public.order_operations(actor,'shipments','{"search":"Rollback batch","stage":2}');
 if jsonb_array_length(result->'shipments')<>2 then raise exception 'Created shipments not listed';end if;
 if not exists(select 1 from jsonb_array_elements(result->'shipments') x where x->>'id'=sid::text) then raise exception 'Created shipment missing from list';end if;
 result:=public.order_operations(actor,'shipments','{"search":"Rollback batch","stage":7}');
 if jsonb_array_length(result->'shipments')<>0 then raise exception 'Shipment stage filter ignored';end if;
 perform public.order_operations(actor,'allocate',jsonb_build_object('shipment_id',sid,'version',1,'items',jsonb_build_array(jsonb_build_object('item_id',iid,'quantity',1))));
 blocked:=false;begin perform public.order_operations(actor,'allocate',jsonb_build_object('shipment_id',sid2,'version',1,'items',jsonb_build_array(jsonb_build_object('item_id',iid,'quantity',2))));exception when raise_exception then blocked:=true;end;if not blocked then raise exception 'Over-allocation accepted';end if;
 perform public.order_operations(actor,'advance',jsonb_build_object('shipment_id',sid,'version',2,'stage',7));
 if(select status from public.orders where id=oid)<>'Payment Made' then raise exception 'Partial delivery marked whole order delivered';end if;
 blocked:=false;begin perform public.cancel_customer_order(actor,'TRK-1794840000000-OPS1');exception when raise_exception then blocked:=true;end;if not blocked then raise exception 'Partially shipped order cancellation accepted';end if;
 perform public.order_operations(actor,'allocate',jsonb_build_object('shipment_id',sid2,'version',1,'items',jsonb_build_array(jsonb_build_object('item_id',iid,'quantity',1))));
 perform public.order_operations(actor,'advance',jsonb_build_object('shipment_id',sid2,'version',2,'stage',3));
 if(select status from public.orders where id=oid)<>'Order Shipped' then raise exception 'Earliest shipment stage incorrect';end if;
 blocked:=false;begin perform public.order_operations(actor,'advance',jsonb_build_object('shipment_id',sid2,'version',2,'stage',7));exception when raise_exception then blocked:=true;end;if not blocked then raise exception 'Stale shipment version accepted';end if;
 perform public.order_operations(actor,'advance',jsonb_build_object('shipment_id',sid2,'version',3,'stage',7));
 if(select status from public.orders where id=oid)<>'Order Delivered' then raise exception 'Full delivery not reflected';end if;
 result:=public.customer_shipment_tracking(actor,oid);if jsonb_array_length(result->'items'->0->'shipments')<>2 then raise exception 'Split tracking not available';end if;
 if jsonb_array_length(public.customer_shipment_tracking('00000000-0000-0000-0000-000000000099',oid)->'items')<>0 then raise exception 'Another customer can track this order';end if;
 blocked:=false;begin perform public.order_operations('00000000-0000-0000-0000-000000000099','orders','{}');exception when raise_exception then blocked:=true;end;if not blocked then raise exception 'Non-admin operations accepted';end if;
 insert into public.orders(order_number,user_id,customer_name,customer_email,contact,items,estimated_total,currency,pricing_verified_at) values('TRK-1794840000000-OPS2',actor,'Rollback fixture','audit@example.test','audit','[{"name":"Test item","quantity":1}]',100,'GHS',now()) returning id into oid;
 insert into public.payment_attempts(reference,order_id,amount,currency)values('TRK-ops-test-reference2',oid,10000,'GHS');
 perform public.finalize_verified_payment(oid,'TRK-ops-test-reference2',tx||jsonb_build_object('reference','TRK-ops-test-reference2','metadata',jsonb_build_object('order_id',oid,'user_id',actor)));
 perform public.cancel_customer_order(actor,'TRK-1794840000000-OPS2');
 if not(select refund_review_required from public.orders where id=oid) then raise exception 'Paid cancellation omitted refund review';end if;
end $$;
set local role service_role;
select public.order_operations((select id from public.orders where order_number='TRK-1794840000000-OPS1'),'orders','{}') where false;
reset role;
select json_build_object('transactional_order_tests','passed','customer_can_execute_admin_rpc',has_function_privilege('authenticated','public.order_operations(uuid,text,jsonb)','EXECUTE'),'anonymous_can_authorize_worker',has_function_privilege('anon','public.authorize_order_worker(text)','EXECUTE'));
rollback;
